        // Normaliza texto: minúsculas y sin tildes
        const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

        // ¿Alguna palabra del texto empieza con lo escrito?
        function matches(option, typed) {
          const t = norm(typed);
          const o = norm(option);
          if (o.startsWith(t)) return true;
          return o.split(/[\s]+/).some(word => word.startsWith(t));
        }

        // Render genérico de la lista de sugerencias
        function renderList(listEl, items, onPick) {
          listEl.innerHTML = '';
          if (!items.length) { listEl.classList.remove('show'); return; }
          items.forEach(it => {
            const div = document.createElement('div');
            div.className = 'ac-item';
            div.textContent = it;
            div.addEventListener('mousedown', e => { e.preventDefault(); onPick(it); });
            listEl.appendChild(div);
          });
          listEl.classList.add('show');
        }

        // ── Región ──
        function filterRegion() {
          const input = document.getElementById('sh-region');
          const list = document.getElementById('region-list');
          const typed = input.value.trim();
          if (!typed) { list.classList.remove('show'); return; }
          const items = Object.keys(CHILE).filter(r => matches(r, typed));
          renderList(list, items, val => {
            input.value = val;
            list.classList.remove('show');
            // limpiar comuna al cambiar de región
            document.getElementById('sh-commune').value = '';
          });
        }

        // ── Comuna (filtra según la región elegida) ──
        function filterComuna() {
          const input = document.getElementById('sh-commune');
          const list = document.getElementById('comuna-list');
          const region = document.getElementById('sh-region').value.trim();
          const typed = input.value.trim();
          if (!typed) { list.classList.remove('show'); return; }

          const key = Object.keys(CHILE).find(r => norm(r) === norm(region))
            || Object.keys(CHILE).find(r => norm(r).includes(norm(region)) && region.length > 2);
          // Si no hay región válida, busca en todas las comunas del país
          const pool = key ? CHILE[key] : Object.values(CHILE).flat();
          const items = pool.filter(c => matches(c, typed));
          renderList(list, items, val => {
            input.value = val;
            list.classList.remove('show');
          });
        }

        // Cerrar las listas al hacer clic fuera
