        const REGION_CODES = {
          'metropolitana': '13', 'valparaiso': '05', 'biobio': '08', 'araucania': '09',
          'los lagos': '10', 'maule': '07', 'coquimbo': '04', 'atacama': '03',
          'antofagasta': '02', 'tarapaca': '01', 'arica': '15', "ohiggins": '06',
          'los rios': '14', 'aysen': '11', 'magallanes': '12', 'nuble': '16',
          'los rios': '14', 'tarapaca': '01'
        };

        function getRegionCode(region) {
          if (!region) return '13';
          const key = region.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z\s]/g,'').trim();
          return REGION_CODES[key] || '13';
        }

        async function calcularEnvio() {
          const region = document.getElementById('sh-region').value.trim();
          const commune = document.getElementById('sh-commune').value.trim();
          const address = document.getElementById('sh-address').value.trim();
          const results = document.getElementById('shipping-results');

          if (!commune) {
            results.innerHTML = '<div class="shipping-error">Ingresa al menos la comuna de destino.</div>';
            return;
          }

          results.innerHTML = '<div class="shipping-msg">Consultando tarifas en tiempo real...</div>';
          document.getElementById('total-row').style.display = 'none';
          selectedShipping = null;

          try {
            const res = await fetch(api('/calcular-envio'), {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ region, commune, city: commune, address, regionCode: getRegionCode(region) })
            });
            const data = await res.json();

            if (!res.ok || !data.carriers?.length) {
              results.innerHTML = `<div class="shipping-error">${data.error || 'No hay opciones de envío para esta dirección.'}</div>`;
              return;
            }

            let html = '<div class="carrier-list">';
            // Opción GRATIS por lanzamiento (destacada, primera)
            const free = { carrier: 'Envío GRATIS por lanzamiento', price: 0, deliveryTime: 'Despacho estándar · 3 a 6 días hábiles', serviceType: 'Promoción' };
            const freeEnc = encodeURIComponent(JSON.stringify(free));
            html += `<label class="carrier-option free-opt" onclick="selectCarrier('${freeEnc}','${encodeURIComponent(commune)}','${encodeURIComponent(region)}','${encodeURIComponent(address)}')">
              <input type="radio" name="carrier" value="free">
              <div style="flex:1"><div class="carrier-name" style="color:#69c46d;">🎉 Envío GRATIS <span style="font-weight:400;color:#888;font-size:.62rem;">por lanzamiento</span></div><div class="carrier-time">Despacho estándar · 3 a 6 días hábiles</div></div>
              <div class="carrier-price" style="color:#69c46d;">GRATIS</div>
            </label>`;
            // Opciones de courier con su precio real (alternativas más rápidas)
            data.carriers.forEach(c => {
              const price = c.price.toLocaleString('es-CL');
              const encoded = encodeURIComponent(JSON.stringify(c));
              html += `<label class="carrier-option" onclick="selectCarrier('${encoded}','${encodeURIComponent(commune)}','${encodeURIComponent(region)}','${encodeURIComponent(address)}')">
                <input type="radio" name="carrier" value="${c.carrier}">
                <div style="flex:1"><div class="carrier-name">${c.carrier}</div><div class="carrier-time">${c.deliveryTime}</div></div>
                <div class="carrier-price">$${price}</div>
              </label>`;
            });
            html += '</div>';
            if (data.errors?.length) {
              html += `<div class="shipping-msg" style="color:#444;margin-top:8px">${data.errors.join(' · ')}</div>`;
            }
            results.innerHTML = html;
          } catch(e) {
            results.innerHTML = `<div class="shipping-error">Error: ${e.message || 'No se pudo conectar con el servidor. ¿Está corriendo npm start?'}</div>`;
            console.error('[calcularEnvio]', e);
          }
        }

        function selectCarrier(encodedCarrier, encodedCommune, encodedRegion, encodedAddress) {
          const carrier = JSON.parse(decodeURIComponent(encodedCarrier));
          const commune = decodeURIComponent(encodedCommune);
          const region = decodeURIComponent(encodedRegion);
          const address = decodeURIComponent(encodedAddress);
          selectedShipping = { ...carrier, address: { commune, region, address } };
          const total = PRODUCT_PRICE + (carrier.price || 0);
          document.getElementById('total-display').textContent = '$' + total.toLocaleString('es-CL');
          document.getElementById('total-row').style.display = 'flex';
          document.querySelectorAll('.carrier-option').forEach(el => el.classList.remove('selected'));
          event.currentTarget.closest('.carrier-option')?.classList.add('selected');
        }

        // ── Abrir / cerrar el checkout ──
        function abrirCheckout() {
          document.getElementById('checkout-overlay').classList.add('show');
          document.body.style.overflow = 'hidden';
          if (window.fbq) fbq('track', 'InitiateCheckout', { value: 34990, currency: 'CLP', content_name: 'DEUS Band' });
        }
        function cerrarCheckout() {
          document.getElementById('checkout-overlay').classList.remove('show');
          document.body.style.overflow = '';
        }
        document.addEventListener('keydown', e => { if (e.key === 'Escape') cerrarCheckout(); });

        // Datos del pedido que se envían a cualquier medio de pago
        function datosPedido() {
          return {
            customerName: document.getElementById('co-nombre').value.trim(),
            customerRut: document.getElementById('co-rut').value.trim(),
            customerEmail: document.getElementById('co-email').value.trim(),
            customerPhone: document.getElementById('co-fono').value.trim(),
            selectedColor: (typeof colorOrder !== 'undefined' ? colorOrder[currentSlide] : null),
            shippingCarrier: selectedShipping?.carrier || null,
            shippingCost: selectedShipping?.price || 0,
            shippingAddress: selectedShipping?.address || null
          };
        }

        // Valida nombre, teléfono y envío antes de pagar
        function validarCheckout(msg) {
          const d = datosPedido();
          msg.style.display = 'block';
          msg.style.color = '#c0392b';
          if (!d.customerName) { msg.textContent = 'Ingresa el nombre de quien recibe.'; return false; }
          if (!d.customerRut) { msg.textContent = 'Ingresa tu RUT.'; return false; }
          if (!d.customerEmail || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.customerEmail)) { msg.textContent = 'Ingresa un correo válido.'; return false; }
          if (!d.customerPhone) { msg.textContent = 'Ingresa un teléfono de contacto.'; return false; }
          if (!selectedShipping) { msg.textContent = 'Calcula y elige una opción de envío.'; return false; }
          return true;
        }

        // ── Pago con Webpay (Transbank) ──
        async function iniciarPagoWebpay() {
          const msg = document.getElementById('mp-msg');
          if (!validarCheckout(msg)) return;
          const wp = document.getElementById('wp-btn');
          wp.disabled = true;
          wp.textContent = 'Redirigiendo a Webpay...';
          msg.style.color = '#666';
          msg.textContent = 'Conectando con Webpay...';
          if (window.fbq) fbq('track', 'AddPaymentInfo', { value: PRODUCT_PRICE + (selectedShipping?.price || 0), currency: 'CLP' });
          try {
            const res = await fetch(api('/webpay/crear'), {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(datosPedido())
            });
            const data = await res.json();
            if (data.url && data.token) {
              // Webpay exige redirigir con un POST que lleva token_ws
              const form = document.createElement('form');
              form.method = 'POST';
              form.action = data.url;
              const input = document.createElement('input');
              input.type = 'hidden';
              input.name = 'token_ws';
              input.value = data.token;
              form.appendChild(input);
              document.body.appendChild(form);
              form.submit();
            } else {
              throw new Error('Sin URL de Webpay');
            }
          } catch (e) {
            wp.disabled = false;
            wp.textContent = 'Pagar con Webpay (Transbank)';
            msg.textContent = 'Error al conectar con Webpay. Intenta nuevamente.';
            msg.style.color = '#c0392b';
          }
        }

        async function iniciarPago() {
          const btn = document.getElementById('mp-btn');
          const msg = document.getElementById('mp-msg');

          const nombre = document.getElementById('co-nombre').value.trim();
          const fono = document.getElementById('co-fono').value.trim();

          // Validaciones antes de pagar
          msg.style.display = 'block';
          msg.style.color = '#c0392b';
          if (!nombre) { msg.textContent = 'Ingresa el nombre de quien recibe.'; return; }
          if (!fono) { msg.textContent = 'Ingresa un teléfono de contacto.'; return; }
          if (!selectedShipping) { msg.textContent = 'Calcula y elige una opción de envío.'; return; }

          btn.disabled = true;
          btn.textContent = 'Procesando...';
          msg.style.color = '#666';
          msg.textContent = 'Preparando pago seguro...';
          if (window.fbq) fbq('track', 'AddPaymentInfo', { value: PRODUCT_PRICE + (selectedShipping?.price || 0), currency: 'CLP' });
          try {
            const res = await fetch(api('/crear-preferencia'), {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                customerName: nombre,
                customerPhone: fono,
                selectedColor: (typeof colorOrder !== 'undefined' ? colorOrder[currentSlide] : null),
                shippingCarrier: selectedShipping?.carrier || null,
                shippingCost: selectedShipping?.price || 0,
                shippingAddress: selectedShipping?.address || null
              })
            });
            const data = await res.json();
            if (data.init_point) {
              window.location.href = data.init_point;
            } else {
              throw new Error('Sin init_point');
            }
          } catch(e) {
            btn.disabled = false;
            btn.textContent = 'Pagar con MercadoPago';
            msg.textContent = 'Error al conectar. Intenta nuevamente.';
            msg.style.color = '#c0392b';
          }
        }
      
