const bandImages = {
  negra: "data:image/jpeg;base64,",
  gris: "data:image/jpeg;base64,",
};
const colorOrder = ['negra','gris'];
let currentSlide = 0;

// Cargar imágenes en los slides
function initSlides() {
  document.querySelectorAll('.slide').forEach(s => {
    const c = s.getAttribute('data-color');
    if (bandImages[c]) s.src = bandImages[c];
  });
}

function goSlide(i) {
  currentSlide = (i + colorOrder.length) % colorOrder.length;
  const slides = document.getElementById('slides');
  if (slides) slides.style.transform = `translateX(-${currentSlide*100}%)`;
  document.querySelectorAll('.sdot').forEach((d,idx) => d.classList.toggle('active', idx===currentSlide));
  document.querySelectorAll('.cdot').forEach((d,idx) => d.classList.toggle('active', idx===currentSlide));
}

function setColor(color, el) {
  const idx = colorOrder.indexOf(color);
  if (idx >= 0) goSlide(idx);
}

// Swipe con el dedo
(function() {
  let startX = 0, isDown = false;
  const slider = document.getElementById('galSlider');
  if (!slider) return;
  slider.addEventListener('touchstart', e => { startX = e.touches[0].clientX; isDown = true; }, {passive:true});
  slider.addEventListener('touchend', e => {
    if (!isDown) return;
    isDown = false;
    const dx = e.changedTouches[0].clientX - startX;
    if (dx < -40) goSlide(currentSlide + 1);
    else if (dx > 40) goSlide(currentSlide - 1);
    else if (Math.abs(dx) < 10) abrirZoom();
  }, {passive:true});
  // Mouse drag para desktop
  slider.addEventListener('mousedown', e => { startX = e.clientX; isDown = true; });
  slider.addEventListener('mouseup', e => {
    if (!isDown) return;
    isDown = false;
    const dx = e.clientX - startX;
    if (dx < -40) goSlide(currentSlide + 1);
    else if (dx > 40) goSlide(currentSlide - 1);
    else if (Math.abs(dx) < 10) abrirZoom();
  });

  let lbIndex = 0;
  function buildLbTrack() {
    const track = document.getElementById('lb-track');
    if (!track || track.dataset.built) return;
    track.innerHTML = colorOrder.map(function(c){ return '<div class="lb-slide"><img src="'+bandImages[c]+'" alt="DEUS Band"></div>'; }).join('');
    track.dataset.built = '1';
  }
  function setTrack(animate) {
    const track = document.getElementById('lb-track');
    track.classList.toggle('anim', !!animate);
    track.style.transform = 'translateX(-' + (lbIndex*100) + '%)';
  }
  function abrirZoom() {
    buildLbTrack();
    lbIndex = currentSlide;
    setTrack(false);
    document.getElementById('lightbox').classList.add('show');
    document.body.style.overflow = 'hidden';
  }
  window.zoomNav = function(dir, e) {
    if (e) e.stopPropagation();
    lbIndex = Math.max(0, Math.min(colorOrder.length - 1, lbIndex + dir));
    setTrack(true);
  };
  window.cerrarZoom = function(e) {
    if (window._lbSwiped) return;
    if (e && e.target && e.target.closest && (e.target.closest('.lb-track') || e.target.closest('.lb-nav'))) return;
    document.getElementById('lightbox').classList.remove('show');
    document.body.style.overflow = '';
  };
  document.addEventListener('keydown', e => {
    var lb = document.getElementById('lightbox');
    if (!lb || !lb.classList.contains('show')) return;
    if (e.key === 'Escape') cerrarZoom();
    else if (e.key === 'ArrowRight') zoomNav(1);
    else if (e.key === 'ArrowLeft') zoomNav(-1);
  });
  // Arrastre con el dedo: la imagen sigue el dedo y al soltar se desliza
  (function(){
    let x0 = 0, dragging = false, w = 0;
    function abierto(){ var lb = document.getElementById('lightbox'); return lb && lb.classList.contains('show'); }
    document.addEventListener('touchstart', e => {
      if (!abierto()) return;
      x0 = e.touches[0].clientX; dragging = true;
      var vp = document.getElementById('lb-viewport'); w = vp ? vp.offsetWidth : window.innerWidth;
      document.getElementById('lb-track').classList.remove('anim');
    }, {passive:true});
    document.addEventListener('touchmove', e => {
      if (!dragging) return;
      var dx = e.touches[0].clientX - x0;
      document.getElementById('lb-track').style.transform = 'translateX(' + (-(lbIndex*100) + (dx/w*100)) + '%)';
    }, {passive:true});
    document.addEventListener('touchend', e => {
      if (!dragging) return; dragging = false;
      var dx = e.changedTouches[0].clientX - x0;
      document.getElementById('lb-track').classList.add('anim');
      if (dx < -40 && lbIndex < colorOrder.length - 1) { lbIndex++; window._lbSwiped = true; setTimeout(function(){window._lbSwiped=false;},400); }
      else if (dx > 40 && lbIndex > 0) { lbIndex--; window._lbSwiped = true; setTimeout(function(){window._lbSwiped=false;},400); }
      setTrack(true);
    }, {passive:true});
  })();
})();

// Contador 24h
function updateCountdown() {
  const now = new Date();
  const tomorrow = new Date(now);
  tomorrow.setHours(24, 0, 0, 0);
  const diff = tomorrow - now;
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const hEl = document.getElementById('cd-h'), mEl = document.getElementById('cd-m'), sEl = document.getElementById('cd-s');
  if (hEl) hEl.textContent = String(h).padStart(2,'0');
  if (mEl) mEl.textContent = String(m).padStart(2,'0');
  if (sEl) sEl.textContent = String(s).padStart(2,'0');
}

document.addEventListener('DOMContentLoaded', function() {
  initSlides();
  updateCountdown();
  setInterval(updateCountdown, 1000);
});
